  "currentTexts": {
    "keyName": {
      "sourceKey": "Spell_ViegoQ_Name",
      "text": "破败王剑"
    },
    "keyTooltip": {
      "sourceKey": "Spell_ViegoQ_Tooltip",
      "text": "<spellPassive>被动：</spellPassive>佛耶戈的攻击造成额外的<physicalDamage>@TotalPercentHealthOnHit@当前生命值的物理伤害</physicalDamage>。如果敌人近期被他用一个技能伤害过，那么他对该敌人的第一次攻击会进行两次打击，造成<physicalDamage>@SecondAttackDamage@物理伤害</physicalDamage>并回复<healing>@HealModVsChamps*100@%实际伤害值的生命值</healing>。这些被动加成会在<keywordMajor>占据</keywordMajor>期间保留。<br><br><spellActive>主动：</spellActive>佛耶戈向前戳刺，造成<physicalDamage>@TotalDamage@物理伤害</physicalDamage>。"
    },
    "keyTooltipExtendedBelowLine": {
      "sourceKey": "Spell_ViegoQ_TooltipExtendedBelowLine",
      "text": "<rules>在未<keywordMajor>占据</keywordMajor>一名敌人时，第二次打击可以暴击并且可以施加%i:OnHit% <OnHit>攻击特效</OnHit>。它的治疗效果在对野怪时降低至@HealModVsMonsters*100@%并且对小兵时降低至@HealModVsMinions*100@%。<br>额外%i:OnHit% <OnHit>攻击特效</OnHit>伤害可以暴击造成<physicalDamage>@HealthCritDamage@当前生命值</physicalDamage>的伤害，并且最小值为<physicalDamage>@MinDamageOnHit@伤害</physicalDamage>。它对野怪的最大伤害值为<physicalDamage>@MonsterCapOnHit@伤害</physicalDamage>。<br>这个技能的施放时间可由攻击速度来缩短。它的伤害受益于暴击几率和暴击伤害，效能为@ActiveCritMod*100@%。</rules>"
    },
    "keySummary": {
      "sourceKey": "Spell_ViegoQ_Summary",
      "text": "佛耶戈的鬼魅之刃会在被动地在命中时造成额外的百分比当前生命值伤害<OnHit>攻击特效</OnHit>，并对近期被他用一个技能袭击过的敌人进行两次打击，同时窃取生命值。<br><br>佛耶戈可以激活这个技能来向前刺出他的双手巨剑，穿刺他前方的所有敌人们。"
    },
    "keyCost": {
      "sourceKey": "Spell_Cost_NoCost",
      "text": "无消耗"
    }
  }
},
